public class Solution {
  /**
   * 事件打包进 long：高位 = 坐标保序平移到 [0, 2^32-1]，低位 = 同一坐标内的处理顺序。
   * touchingSharesSlot 决定"进入"排在"退出"之前（相接算并发）还是之后（相接不算并发）。
   * O(n log n) 时间、O(n) 空间；全程没有 end + 1，因此 MAX_VALUE 端点安全。
   */
  public static int peakConcurrentSessions(int[] startSecs, int[] endSecs, boolean touchingSharesSlot) {
    if (startSecs.length != endSecs.length) {
      throw new IllegalArgumentException("length mismatch");
    }
    int n = startSecs.length;
    if (n == 0) return 0;
    long inBit = touchingSharesSlot ? 0L : 1L;
    long outBit = touchingSharesSlot ? 1L : 0L;
    long[] events = new long[n * 2];
    for (int k = 0; k < n; k++) {
      int a = startSecs[k];
      int b = endSecs[k];
      if (b < a) throw new IllegalArgumentException("end before start");
      long ta = (long) a - Integer.MIN_VALUE;
      long tb = (long) b - Integer.MIN_VALUE;
      events[2 * k] = (ta << 1) | inBit;
      events[2 * k + 1] = (tb << 1) | outBit;
    }
    java.util.Arrays.sort(events);
    int peak = 0;
    int cur = 0;
    for (long ev : events) {
      cur += (ev & 1L) == inBit ? 1 : -1;
      if (cur > peak) peak = cur;
    }
    return peak;
  }
}

