public class Solution {
  // 朴素：开始/结束各自排序后双指针。省掉了"同一坐标内的事件类型"这一位，
  // 于是先处理进入还是先处理退出变成比较符的巧合，touchingSharesSlot 被静默忽略。
  public static int peakConcurrentSessions(int[] startSecs, int[] endSecs, boolean touchingSharesSlot) {
    if (startSecs.length != endSecs.length) {
      throw new IllegalArgumentException("length mismatch");
    }
    int[] a = startSecs.clone();
    int[] b = endSecs.clone();
    java.util.Arrays.sort(a);
    java.util.Arrays.sort(b);
    int cur = 0;
    int peak = 0;
    int j = 0;
    for (int value : a) {
      while (j < b.length && b[j] < value) {
        cur--;
        j++;
      }
      cur++;
      if (cur > peak) peak = cur;
    }
    return peak;
  }
}
